window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2023-shanghai"]=[{"id":"2023-shanghai-q01","paperId":"2023-shanghai","number":1,"type":"fill","score":4,"lessonIds":["2.1"],"difficulty":"基础","hint":"|x−2|<1就是x到2的距离小于1，先写成−1<x−2<1。","legacy":false,"legacyReason":"","searchText":"设 x\\in\\R ，不等式 \\left|x-2\\right|<1 的解集为 ________ . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"x\\in\\R\">x\\in\\R</span>，不等式 <span class=\"gk-math\" data-tex=\"\\left|x-2\\right|&lt;1\">\\left|x-2\\right|&lt;1</span> 的解集为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\left(1,3\\right)\">\\left(1,3\\right)</span>","answerKey":"","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\left|x-2\\right|&lt;1\">\\left|x-2\\right|&lt;1</span> 得 <span class=\"gk-math\" data-tex=\"-1&lt;x-2&lt;1\">-1&lt;x-2&lt;1</span>，所以 <span class=\"gk-math\" data-tex=\"1&lt;x&lt;3\">1&lt;x&lt;3</span>，故解集为 <span class=\"gk-math\" data-tex=\"\\left(1,3\\right)\">\\left(1,3\\right)</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q02","paperId":"2023-shanghai","number":2,"type":"fill","score":4,"lessonIds":["6.3"],"difficulty":"基础","hint":"数量积等于横坐标相乘加纵坐标相乘。","legacy":false,"legacyReason":"","searchText":"若向量 \\bs a=\\left(-2,3\\right) ， \\bs b=\\left(1,2\\right) ，则 \\bs a\\cdot\\bs b=\\fillinblank{} . ","questionHtml":"若向量 <span class=\"gk-math\" data-tex=\"\\bs a=\\left(-2,3\\right)\">\\bs a=\\left(-2,3\\right)</span>，<span class=\"gk-math\" data-tex=\"\\bs b=\\left(1,2\\right)\">\\bs b=\\left(1,2\\right)</span>，则 <span class=\"gk-math\" data-tex=\"\\bs a\\cdot\\bs b=\\fillinblank{}\">\\bs a\\cdot\\bs b=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"4\">4</span>","answerKey":"","solutionHtml":"由向量数量积的坐标公式，<span class=\"gk-math\" data-tex=\"\\bs a\\cdot\\bs b=\\left(-2\\right)\\times 1+3\\times 2=4\">\\bs a\\cdot\\bs b=\\left(-2\\right)\\times 1+3\\times 2=4</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q03","paperId":"2023-shanghai","number":3,"type":"fill","score":4,"lessonIds":["e2-4.3"],"difficulty":"基础","hint":"把首项3、公比2、项数6代入等比数列求和公式。","legacy":false,"legacyReason":"","searchText":"若数列 \\{a_n\\} 是首项为 3 ，公比为 2 的等比数列，其前 n 项和为 S_n ，则 S_6=\\fillinblank{} . ","questionHtml":"若数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 是首项为 <span class=\"gk-math\" data-tex=\"3\">3</span>，公比为 <span class=\"gk-math\" data-tex=\"2\">2</span> 的等比数列，其前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和为 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span>，则 <span class=\"gk-math\" data-tex=\"S_6=\\fillinblank{}\">S_6=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"189\">189</span>","answerKey":"","solutionHtml":"由等比数列前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和公式 <span class=\"gk-math\" data-tex=\"S_n=3\\times \\frac{1-2^n}{1-2}\">S_n=3\\times \\frac{1-2^n}{1-2}</span>，得 <span class=\"gk-math\" data-tex=\"S_6=3\\times \\frac{1-2^6}{1-2}=3\\times 63=189\">S_6=3\\times \\frac{1-2^6}{1-2}=3\\times 63=189</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q04","paperId":"2023-shanghai","number":4,"type":"fill","score":4,"lessonIds":["5.5"],"difficulty":"基础","hint":"用tan2A=2tanA/(1−tan²A)。","legacy":false,"legacyReason":"","searchText":"若 \\tan A=3 ，则 \\tan 2A=\\fillinblank{} . ","questionHtml":"若 <span class=\"gk-math\" data-tex=\"\\tan A=3\">\\tan A=3</span>，则 <span class=\"gk-math\" data-tex=\"\\tan 2A=\\fillinblank{}\">\\tan 2A=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"-\\frac34\">-\\frac34</span>","answerKey":"","solutionHtml":"由正切二倍角公式 <span class=\"gk-math\" data-tex=\"\\tan 2A=\\frac{2\\tan A}{1-\\tan^2 A}\">\\tan 2A=\\frac{2\\tan A}{1-\\tan^2 A}</span>，代入 <span class=\"gk-math\" data-tex=\"\\tan A=3\">\\tan A=3</span> 得 <span class=\"gk-math\" data-tex=\"\\tan 2A=\\frac{2\\times 3}{1-3^2}=-\\frac34\">\\tan 2A=\\frac{2\\times 3}{1-3^2}=-\\frac34</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q05","paperId":"2023-shanghai","number":5,"type":"fill","score":4,"lessonIds":["3.1","4.2"],"difficulty":"基础","hint":"分x≤0和x>0两部分，分别列出能取得的y，再合并。","legacy":false,"legacyReason":"","searchText":"函数 y=\\begin{cases} 2^x,&x>0,\\\\ 1,&x\\le 0, \\end{cases} 的值域为 ________ . ","questionHtml":"函数 <span class=\"gk-math\" data-tex=\"y=\\begin{cases}\n2^x,&amp;x&gt;0,\\\\\n1,&amp;x\\le 0,\n\\end{cases}\">y=\\begin{cases}\n2^x,&amp;x&gt;0,\\\\\n1,&amp;x\\le 0,\n\\end{cases}</span> 的值域为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\left[1,+\\infty\\right)\">\\left[1,+\\infty\\right)</span>","answerKey":"","solutionHtml":"当 <span class=\"gk-math\" data-tex=\"x\\le 0\">x\\le 0</span> 时，<span class=\"gk-math\" data-tex=\"y=1\">y=1</span>；当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时，<span class=\"gk-math\" data-tex=\"y=2^x&gt;2^0=1\">y=2^x&gt;2^0=1</span>，所以 <span class=\"gk-math\" data-tex=\"y\">y</span> 的取值恒满足 <span class=\"gk-math\" data-tex=\"y\\ge 1\">y\\ge 1</span>，且 <span class=\"gk-math\" data-tex=\"1\">1</span> 与大于 <span class=\"gk-math\" data-tex=\"1\">1</span> 的每个值都能取到，故值域为 <span class=\"gk-math\" data-tex=\"\\left[1,+\\infty\\right)\">\\left[1,+\\infty\\right)</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q06","paperId":"2023-shanghai","number":6,"type":"fill","score":4,"lessonIds":["7.1","7.2"],"difficulty":"基础","hint":"先算iz，再把1−iz写成a+bi，最后求模。","legacy":false,"legacyReason":"","searchText":"若复数 z=1+\\i （ \\i 为虚数单位），则 \\left|1-\\i z\\right|=\\fillinblank{} . ","questionHtml":"若复数 <span class=\"gk-math\" data-tex=\"z=1+\\i\">z=1+\\i</span>（<span class=\"gk-math\" data-tex=\"\\i\">\\i</span> 为虚数单位），则 <span class=\"gk-math\" data-tex=\"\\left|1-\\i z\\right|=\\fillinblank{}\">\\left|1-\\i z\\right|=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\sqrt5\">\\sqrt5</span>","answerKey":"","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"z=1+\\i\">z=1+\\i</span> 得 <span class=\"gk-math\" data-tex=\"1-\\i z=1-\\i\\left(1+\\i\\right)=1-\\i-\\i^2=2-\\i\">1-\\i z=1-\\i\\left(1+\\i\\right)=1-\\i-\\i^2=2-\\i</span>，所以 <span class=\"gk-math\" data-tex=\"\\left|1-\\i z\\right|=\\sqrt{2^2+\\left(-1\\right)^2}=\\sqrt5\">\\left|1-\\i z\\right|=\\sqrt{2^2+\\left(-1\\right)^2}=\\sqrt5</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q07","paperId":"2023-shanghai","number":7,"type":"fill","score":5,"lessonIds":["e1-2.4"],"difficulty":"基础","hint":"配方成x²+(y−2)²=r²，再由面积π求r。","legacy":false,"legacyReason":"","searchText":"设 m\\in\\R . 若圆 x^2+y^2-4y-m=0 的面积为 \\pi ，则 m=\\fillinblank{} . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"m\\in\\R\">m\\in\\R</span>. 若圆 <span class=\"gk-math\" data-tex=\"x^2+y^2-4y-m=0\">x^2+y^2-4y-m=0</span> 的面积为 <span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span>，则 <span class=\"gk-math\" data-tex=\"m=\\fillinblank{}\">m=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"-3\">-3</span>","answerKey":"","solutionHtml":"配方得 <span class=\"gk-math\" data-tex=\"x^2+\\left(y-2\\right)^2=m+4\">x^2+\\left(y-2\\right)^2=m+4</span>，故该方程表示圆当且仅当 <span class=\"gk-math\" data-tex=\"m+4&gt;0\">m+4&gt;0</span>，此时半径 <span class=\"gk-math\" data-tex=\"r=\\sqrt{m+4}\">r=\\sqrt{m+4}</span>，由面积为 <span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span> 得 <span class=\"gk-math\" data-tex=\"r=1\">r=1</span>，于是 <span class=\"gk-math\" data-tex=\"m+4=1\">m+4=1</span>，解得 <span class=\"gk-math\" data-tex=\"m=-3\">m=-3</span>，满足 <span class=\"gk-math\" data-tex=\"m+4&gt;0\">m+4&gt;0</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q08","paperId":"2023-shanghai","number":8,"type":"fill","score":5,"lessonIds":["6.4"],"difficulty":"基础","hint":"先用余弦定理求cosA，再用sin²A+cos²A=1。","legacy":false,"legacyReason":"","searchText":"在 \\triangle ABC 中，角 A ， B ， C 所对的边长分别为 a ， b ， c . 若 a=4 ， b=5 ， c=6 ，则 \\sin A=\\fillinblank{} . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，角 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 所对的边长分别为 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span>. 若 <span class=\"gk-math\" data-tex=\"a=4\">a=4</span>，<span class=\"gk-math\" data-tex=\"b=5\">b=5</span>，<span class=\"gk-math\" data-tex=\"c=6\">c=6</span>，则 <span class=\"gk-math\" data-tex=\"\\sin A=\\fillinblank{}\">\\sin A=\\fillinblank{}</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\frac{\\sqrt7}{4}\">\\frac{\\sqrt7}{4}</span>","answerKey":"","solutionHtml":"由余弦定理 <span class=\"gk-math\" data-tex=\"\\cos A=\\frac{b^2+c^2-a^2}{2bc}=\\frac{25+36-16}{2\\times 5\\times 6}=\\frac34\">\\cos A=\\frac{b^2+c^2-a^2}{2bc}=\\frac{25+36-16}{2\\times 5\\times 6}=\\frac34</span>，因为 <span class=\"gk-math\" data-tex=\"A\">A</span> 为三角形内角，<span class=\"gk-math\" data-tex=\"\\sin A&gt;0\">\\sin A&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"\\sin A=\\sqrt{1-\\cos^2 A}=\\sqrt{1-\\frac{9}{16}}=\\frac{\\sqrt7}{4}\">\\sin A=\\sqrt{1-\\cos^2 A}=\\sqrt{1-\\frac{9}{16}}=\\frac{\\sqrt7}{4}</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q09","paperId":"2023-shanghai","number":9,"type":"fill","score":5,"lessonIds":["9.2"],"difficulty":"进阶","hint":"把第二、三季度记成b、c，用中位数等于平均数列方程。","legacy":false,"legacyReason":"","searchText":"国内生产总值（GDP）是衡量地区经济状况的最佳指标. 根据统计数据显示，某市在 2020 年间经济高质量增长，GDP 稳步增长，第一季度和第四季度的 GDP 分别为 232 亿元和 241 亿元，且四个季度 GDP 逐季度增长. 若这四个季度 GDP 的中位数与平均数相等，则该市 2020 年的 GDP 总额为 ________ 亿元. ","questionHtml":"国内生产总值（GDP）是衡量地区经济状况的最佳指标. 根据统计数据显示，某市在 2020 年间经济高质量增长，GDP 稳步增长，第一季度和第四季度的 GDP 分别为 <span class=\"gk-math\" data-tex=\"232\">232</span> 亿元和 <span class=\"gk-math\" data-tex=\"241\">241</span> 亿元，且四个季度 GDP 逐季度增长. 若这四个季度 GDP 的中位数与平均数相等，则该市 2020 年的 GDP 总额为<span class=\"gk-blank\" aria-label=\"填空\">________</span> 亿元.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"946\">946</span>","answerKey":"","solutionHtml":"设第二，三季度的GDP分别为 <span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span>（单位为亿元），则四个季度依次为 <span class=\"gk-math\" data-tex=\"232\">232</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span>，<span class=\"gk-math\" data-tex=\"241\">241</span>，且逐季度增长，故 <span class=\"gk-math\" data-tex=\"232\\le b\\le c\\le 241\">232\\le b\\le c\\le 241</span>. 中位数为 <span class=\"gk-math\" data-tex=\"\\frac{b+c}{2}\">\\frac{b+c}{2}</span>，平均数为 <span class=\"gk-math\" data-tex=\"\\frac{232+b+c+241}{4}\">\\frac{232+b+c+241}{4}</span>. 由两者相等得 <span class=\"gk-math\" data-tex=\"\\frac{b+c}{2}=\\frac{232+b+c+241}{4}\">\\frac{b+c}{2}=\\frac{232+b+c+241}{4}</span>，化简得 <span class=\"gk-math\" data-tex=\"b+c=473\">b+c=473</span>. 故全年总额为 <span class=\"gk-math\" data-tex=\"232+b+c+241=232+473+241=946\">232+b+c+241=232+473+241=946</span>. 例如取 <span class=\"gk-math\" data-tex=\"b=235\">b=235</span>，<span class=\"gk-math\" data-tex=\"c=238\">c=238</span>即满足逐季度增长，故该取值可实现.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q10","paperId":"2023-shanghai","number":10,"type":"fill","score":5,"lessonIds":["e3-6.3"],"difficulty":"进阶","hint":"写出xᵏ的系数；先看k是偶数还是奇数，再比较2023的两个幂。","legacy":false,"legacyReason":"","searchText":"已知对任意给定的实数 x ，都有 \\left(1+2023x\\right)^{100}+\\left(2023-x\\right)^{100}=a_0+a_1x+a_2x^2+\\cdots+a_{100}x^{100}, 其中 a_0 ， a_1 ， \\cdots ， a_{100}\\in\\R . 若 a_k<0 ，其中 k\\in\\{0,1,2,\\cdots,100\\} ，则正整数 k 的最大值为 ________ . ","questionHtml":"已知对任意给定的实数 <span class=\"gk-math\" data-tex=\"x\">x</span>，都有 <span class=\"gk-math\" data-tex=\"\\left(1+2023x\\right)^{100}+\\left(2023-x\\right)^{100}=a_0+a_1x+a_2x^2+\\cdots+a_{100}x^{100},\">\\left(1+2023x\\right)^{100}+\\left(2023-x\\right)^{100}=a_0+a_1x+a_2x^2+\\cdots+a_{100}x^{100},</span> 其中 <span class=\"gk-math\" data-tex=\"a_0\">a_0</span>，<span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"\\cdots\">\\cdots</span>，<span class=\"gk-math\" data-tex=\"a_{100}\\in\\R\">a_{100}\\in\\R</span>. 若 <span class=\"gk-math\" data-tex=\"a_k&lt;0\">a_k&lt;0</span>，其中 <span class=\"gk-math\" data-tex=\"k\\in\\{0,1,2,\\cdots,100\\}\">k\\in\\{0,1,2,\\cdots,100\\}</span>，则正整数 <span class=\"gk-math\" data-tex=\"k\">k</span> 的最大值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"49\">49</span>","answerKey":"","solutionHtml":"由二项式定理比较 <span class=\"gk-math\" data-tex=\"x^{k}\">x^{k}</span> 的系数，得 <span class=\"gk-math\" data-tex=\"a_{k}=\\mathrm C_{100}^{k}2023^{k}+\\mathrm C_{100}^{k}\\left(-1\\right)^{k}2023^{100-k}=\\mathrm C_{100}^{k}\\left(2023^{k}+\\left(-1\\right)^{k}2023^{100-k}\\right)\">a_{k}=\\mathrm C_{100}^{k}2023^{k}+\\mathrm C_{100}^{k}\\left(-1\\right)^{k}2023^{100-k}=\\mathrm C_{100}^{k}\\left(2023^{k}+\\left(-1\\right)^{k}2023^{100-k}\\right)</span>. 当 <span class=\"gk-math\" data-tex=\"k\">k</span>为偶数时，<span class=\"gk-math\" data-tex=\"a_{k}=\\mathrm C_{100}^{k}\\left(2023^{k}+2023^{100-k}\\right)&gt;0\">a_{k}=\\mathrm C_{100}^{k}\\left(2023^{k}+2023^{100-k}\\right)&gt;0</span>. 当 <span class=\"gk-math\" data-tex=\"k\">k</span>为奇数时，<span class=\"gk-math\" data-tex=\"a_{k}=\\mathrm C_{100}^{k}\\left(2023^{k}-2023^{100-k}\\right)\">a_{k}=\\mathrm C_{100}^{k}\\left(2023^{k}-2023^{100-k}\\right)</span>. 此时 <span class=\"gk-math\" data-tex=\"a_{k}&lt;0\">a_{k}&lt;0</span>当且仅当 <span class=\"gk-math\" data-tex=\"2023^{k}&lt;2023^{100-k}\">2023^{k}&lt;2023^{100-k}</span>，即 <span class=\"gk-math\" data-tex=\"k&lt;100-k\">k&lt;100-k</span>，亦即 <span class=\"gk-math\" data-tex=\"k&lt;50\">k&lt;50</span>. 故满足 <span class=\"gk-math\" data-tex=\"a_{k}&lt;0\">a_{k}&lt;0</span>的正整数 <span class=\"gk-math\" data-tex=\"k\">k</span>必为小于 <span class=\"gk-math\" data-tex=\"50\">50</span>的奇数，其最大值为 <span class=\"gk-math\" data-tex=\"49\">49</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q11","paperId":"2023-shanghai","number":11,"type":"fill","score":5,"lessonIds":["5.7","e2-5.3"],"difficulty":"挑战","hint":"路程不是4米，而是4/sinθ；把“每米消耗×路程”写出来再求最小值。","legacy":false,"legacyReason":"","searchText":"某公园欲建设一段斜坡，斜坡面是一平面，坡面与水平地面所成角为 \\theta ，坡顶距离水平地面的垂直高度为 4 米，游客从坡底沿着斜坡面向上直行，每走 1 米消耗的体力为 1.025-\\cos\\theta ，当 \\theta=\\fillinblank{} 时，游客走斜坡所消耗的总体力最小. ","questionHtml":"某公园欲建设一段斜坡，斜坡面是一平面，坡面与水平地面所成角为 <span class=\"gk-math\" data-tex=\"\\theta\">\\theta</span>，坡顶距离水平地面的垂直高度为 <span class=\"gk-math\" data-tex=\"4\">4</span> 米，游客从坡底沿着斜坡面向上直行，每走 <span class=\"gk-math\" data-tex=\"1\">1</span> 米消耗的体力为 <span class=\"gk-math\" data-tex=\"1.025-\\cos\\theta\">1.025-\\cos\\theta</span>，当 <span class=\"gk-math\" data-tex=\"\\theta=\\fillinblank{}\">\\theta=\\fillinblank{}</span> 时，游客走斜坡所消耗的总体力最小.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\arccos\\frac{40}{41}\">\\arccos\\frac{40}{41}</span>","answerKey":"","solutionHtml":"记 <span class=\"gk-math\" data-tex=\"\\theta\\in\\left(0,\\frac{\\pi}{2}\\right)\">\\theta\\in\\left(0,\\frac{\\pi}{2}\\right)</span>，斜坡长为 <span class=\"gk-math\" data-tex=\"\\frac{4}{\\sin\\theta}\">\\frac{4}{\\sin\\theta}</span>，总体力为 <span class=\"gk-math\" data-tex=\"E\\left(\\theta\\right)=\\frac{4\\left(1.025-\\cos\\theta\\right)}{\\sin\\theta}\">E\\left(\\theta\\right)=\\frac{4\\left(1.025-\\cos\\theta\\right)}{\\sin\\theta}</span>. 记 <span class=\"gk-math\" data-tex=\"a=1.025=\\frac{41}{40}\">a=1.025=\\frac{41}{40}</span>，则 <span class=\"gk-math\" data-tex=\"E\\left(\\theta\\right)=\\frac{4\\left(a-\\cos\\theta\\right)}{\\sin\\theta}\">E\\left(\\theta\\right)=\\frac{4\\left(a-\\cos\\theta\\right)}{\\sin\\theta}</span>. 求导得 <span class=\"gk-math\" data-tex=\"E^{\\prime}\\left(\\theta\\right)=\\frac{4\\left(1-a\\cos\\theta\\right)}{\\sin^{2}\\theta}\">E^{\\prime}\\left(\\theta\\right)=\\frac{4\\left(1-a\\cos\\theta\\right)}{\\sin^{2}\\theta}</span>. 令 <span class=\"gk-math\" data-tex=\"E^{\\prime}\\left(\\theta\\right)=0\">E^{\\prime}\\left(\\theta\\right)=0</span>得 <span class=\"gk-math\" data-tex=\"\\cos\\theta=\\frac{1}{a}=\\frac{40}{41}\">\\cos\\theta=\\frac{1}{a}=\\frac{40}{41}</span>. 因为 <span class=\"gk-math\" data-tex=\"\\cos\\theta\">\\cos\\theta</span>在 <span class=\"gk-math\" data-tex=\"\\left(0,\\frac{\\pi}{2}\\right)\">\\left(0,\\frac{\\pi}{2}\\right)</span>上严格递减，故总体力先减后增，在 <span class=\"gk-math\" data-tex=\"\\cos\\theta=\\frac{40}{41}\">\\cos\\theta=\\frac{40}{41}</span>处取得最小值，即 <span class=\"gk-math\" data-tex=\"\\theta=\\arccos\\frac{40}{41}\">\\theta=\\arccos\\frac{40}{41}</span>时总体力最小.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q12","paperId":"2023-shanghai","number":12,"type":"fill","score":5,"lessonIds":["8.1","e3-6.1","e1-1.3"],"difficulty":"挑战","hint":"等边三角形的三点不可能全是正方形底面顶点，先分类谁是锥顶。","legacy":false,"legacyReason":"","searchText":"空间中有三个定点 A ， B ， C ，且 AB=BC=CA=1 . 若在空间中任取 2 个不同的点，使它们与 A ， B ， C 恰好成为一个正四棱锥的五个顶点，则不同的取法共有 ________ 种. ","questionHtml":"空间中有三个定点 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span>，且 <span class=\"gk-math\" data-tex=\"AB=BC=CA=1\">AB=BC=CA=1</span>. 若在空间中任取 <span class=\"gk-math\" data-tex=\"2\">2</span> 个不同的点，使它们与 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 恰好成为一个正四棱锥的五个顶点，则不同的取法共有<span class=\"gk-blank\" aria-label=\"填空\">________</span> 种.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"9\">9</span>","answerKey":"","solutionHtml":"正四棱锥指底面为正方形且顶点在底面的投影为中心的棱锥，记底面边长为 <span class=\"gk-math\" data-tex=\"s\">s</span>，侧棱长为 <span class=\"gk-math\" data-tex=\"l\">l</span>，则底面相邻两顶点距离为 <span class=\"gk-math\" data-tex=\"s\">s</span>，相对两顶点距离为 <span class=\"gk-math\" data-tex=\"s\\sqrt{2}\">s\\sqrt{2}</span>，顶点到任一底面顶点的距离为 <span class=\"gk-math\" data-tex=\"l\">l</span>. 设五个顶点中 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span>两两距离为 <span class=\"gk-math\" data-tex=\"1\">1</span>. 若 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span>均为底面顶点，则其中三点为正方形三顶点，必为等腰直角三角形，不可能边长全为 <span class=\"gk-math\" data-tex=\"1\">1</span>，故舍去. 于是 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span>中恰一点为锥顶，另两点为底面顶点. 若另两点在底面相邻，则 <span class=\"gk-math\" data-tex=\"s=1\">s=1</span>，<span class=\"gk-math\" data-tex=\"l=1\">l=1</span>，高 <span class=\"gk-math\" data-tex=\"h=\\sqrt{l^{2}-\\left(s/\\sqrt{2}\\right)^{2}}=\\frac{1}{\\sqrt{2}}&gt;0\">h=\\sqrt{l^{2}-\\left(s/\\sqrt{2}\\right)^{2}}=\\frac{1}{\\sqrt{2}}&gt;0</span>，可行；若另两点在底面相对，则对角线长为 <span class=\"gk-math\" data-tex=\"1\">1</span>，故 <span class=\"gk-math\" data-tex=\"s=\\frac{1}{\\sqrt{2}}\">s=\\frac{1}{\\sqrt{2}}</span>，<span class=\"gk-math\" data-tex=\"l=1\">l=1</span>，高 <span class=\"gk-math\" data-tex=\"h=\\sqrt{1-\\left(\\frac{1}{2}\\right)^{2}}=\\frac{\\sqrt{3}}{2}&gt;0\">h=\\sqrt{1-\\left(\\frac{1}{2}\\right)^{2}}=\\frac{\\sqrt{3}}{2}&gt;0</span>，可行. 别无其他情形. 固定锥顶的选择有 <span class=\"gk-math\" data-tex=\"3\">3</span>种. 当另两点相邻时，以 <span class=\"gk-math\" data-tex=\"C\">C</span>为锥顶、<span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>为底面相邻顶点为例，建坐标 <span class=\"gk-math\" data-tex=\"A\\left(-\\frac12,0,0\\right)\">A\\left(-\\frac12,0,0\\right)</span>，<span class=\"gk-math\" data-tex=\"B\\left(\\frac12,0,0\\right)\">B\\left(\\frac12,0,0\\right)</span>，<span class=\"gk-math\" data-tex=\"C\\left(0,\\frac{\\sqrt{3}}{2},0\\right)\">C\\left(0,\\frac{\\sqrt{3}}{2},0\\right)</span>. 底面中心 <span class=\"gk-math\" data-tex=\"O=\\left(0,y_{0},z_{0}\\right)\">O=\\left(0,y_{0},z_{0}\\right)</span>满足 <span class=\"gk-math\" data-tex=\"\\left|OA\\right|=\\frac{1}{\\sqrt{2}}\">\\left|OA\\right|=\\frac{1}{\\sqrt{2}}</span>，即 <span class=\"gk-math\" data-tex=\"y_{0}^{2}+z_{0}^{2}=\\frac14\">y_{0}^{2}+z_{0}^{2}=\\frac14</span>，且 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CO}\">\\overrightarrow{CO}</span>垂直于底面，故 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CO}\\cdot\\overrightarrow{OA}=0\">\\overrightarrow{CO}\\cdot\\overrightarrow{OA}=0</span>，算得 <span class=\"gk-math\" data-tex=\"y_{0}=\\frac{\\sqrt{3}}{6}\">y_{0}=\\frac{\\sqrt{3}}{6}</span>，<span class=\"gk-math\" data-tex=\"z_{0}^{2}=\\frac16\">z_{0}^{2}=\\frac16</span>. 于是 <span class=\"gk-math\" data-tex=\"z_{0}\">z_{0}</span>有正负两解，各唯一确定底面平面及经中心对称的另两顶点，即无序点对有两个；三个锥顶选择共得 <span class=\"gk-math\" data-tex=\"3\\times 2=6\">3\\times 2=6</span>个. 当另两点相对时，以 <span class=\"gk-math\" data-tex=\"C\">C</span>为锥顶、<span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>为对角线为例，记 <span class=\"gk-math\" data-tex=\"M\">M</span>为 <span class=\"gk-math\" data-tex=\"AB\">AB</span>中点，则中心必为 <span class=\"gk-math\" data-tex=\"M\">M</span>，底面为过 <span class=\"gk-math\" data-tex=\"M\">M</span>且法向量为 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CM}\">\\overrightarrow{CM}</span>的平面，唯一；另两顶点为该平面内过 <span class=\"gk-math\" data-tex=\"M\">M</span>且垂直于 <span class=\"gk-math\" data-tex=\"AB\">AB</span>的直线上到 <span class=\"gk-math\" data-tex=\"M\">M</span>距离为 <span class=\"gk-math\" data-tex=\"\\frac12\">\\frac12</span>的两点，作为无序点对唯一. 三个锥顶选择共得 <span class=\"gk-math\" data-tex=\"3\">3</span>个. 两类距离图不同，且锥顶是唯一与其余四点距离全为 <span class=\"gk-math\" data-tex=\"1\">1</span>的点，故上述 <span class=\"gk-math\" data-tex=\"6+3=9\">6+3=9</span>个无序点对两两不同. 所以不同的取法共有 <span class=\"gk-math\" data-tex=\"9\">9</span>种.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q13","paperId":"2023-shanghai","number":13,"type":"single","score":4,"lessonIds":["1.3"],"difficulty":"基础","hint":"先从P中找出不属于Q的元素。","legacy":false,"legacyReason":"","searchText":"已知集合 P=\\{1,2\\} ， Q=\\{2,3\\} . 若 M=\\{x\\mid x\\in P,\\ x\\notin Q\\} ，则 M= （ ）. \\{1\\} \\{2\\} \\{3\\} \\{1,2,3\\}","questionHtml":"已知集合 <span class=\"gk-math\" data-tex=\"P=\\{1,2\\}\">P=\\{1,2\\}</span>，<span class=\"gk-math\" data-tex=\"Q=\\{2,3\\}\">Q=\\{2,3\\}</span>. 若 <span class=\"gk-math\" data-tex=\"M=\\{x\\mid x\\in P,\\ x\\notin Q\\}\">M=\\{x\\mid x\\in P,\\ x\\notin Q\\}</span>，则 <span class=\"gk-math\" data-tex=\"M=\">M=</span>（ ）.","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{1\\}\">\\{1\\}</span>","<span class=\"gk-math\" data-tex=\"\\{2\\}\">\\{2\\}</span>","<span class=\"gk-math\" data-tex=\"\\{3\\}\">\\{3\\}</span>","<span class=\"gk-math\" data-tex=\"\\{1,2,3\\}\">\\{1,2,3\\}</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"P=\\{1,2\\}\">P=\\{1,2\\}</span>，<span class=\"gk-math\" data-tex=\"Q=\\{2,3\\}\">Q=\\{2,3\\}</span>，<span class=\"gk-math\" data-tex=\"M=\\{x\\mid x\\in P,x\\notin Q\\}\">M=\\{x\\mid x\\in P,x\\notin Q\\}</span>恰为属于 <span class=\"gk-math\" data-tex=\"P\">P</span>但不属于 <span class=\"gk-math\" data-tex=\"Q\">Q</span>的元素，即 <span class=\"gk-math\" data-tex=\"M=\\{1\\}\">M=\\{1\\}</span>. 故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q14","paperId":"2023-shanghai","number":14,"type":"single","score":4,"lessonIds":["e3-8.1"],"difficulty":"基础","hint":"看散点整体是从左下走向右上，还是相反；趋势不等于每个人都严格一样。","legacy":false,"legacyReason":"","searchText":"为了解某校高中男生身高与体重的关系，随机选取 50 名男生的身高与体重的数据，绘制散点图，如图所示，下列说法正确的是（ ）. 身高越高，体重越重 身高越高，体重越轻 身高与体重之间呈正相关 身高与体重之间呈负相关","questionHtml":"为了解某校高中男生身高与体重的关系，随机选取 <span class=\"gk-math\" data-tex=\"50\">50</span> 名男生的身高与体重的数据，绘制散点图，如图所示，下列说法正确的是（ ）.<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,1366px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/shanghai/q14_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/shanghai/q14_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"1350\" height=\"706\" style=\"aspect-ratio:1350/706;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["身高越高，体重越重","身高越高，体重越轻","身高与体重之间呈正相关","身高与体重之间呈负相关"],"answerHtml":"C","answerKey":"C","solutionHtml":"散点图横轴为身高，纵轴为体重，点云总体随身高增大而上移，但并非严格单调，且有个别偏离点. 这正是正相关的统计特征，而不是“身高越高体重一定越重”的确定性断言. 故身高与体重之间呈正相关，选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q15","paperId":"2023-shanghai","number":15,"type":"single","score":5,"lessonIds":["5.4"],"difficulty":"挑战","hint":"试着从t>0出发：区间[2a,3a]必须全部落在正弦曲线的正值部分。","legacy":false,"legacyReason":"","searchText":"已知 a>0 ，函数 y=\\sin x 在区间 \\left[a,2a\\right] 上的最小值为 s ，在区间 \\left[2a,3a\\right] 上的最小值为 t ，当 a 变化时，下列一定不成立的是（ ）. s>0,t>0 s>0 ， t<0 s<0 ， t<0 s<0 ， t>0","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，函数 <span class=\"gk-math\" data-tex=\"y=\\sin x\">y=\\sin x</span> 在区间 <span class=\"gk-math\" data-tex=\"\\left[a,2a\\right]\">\\left[a,2a\\right]</span> 上的最小值为 <span class=\"gk-math\" data-tex=\"s\">s</span>，在区间 <span class=\"gk-math\" data-tex=\"\\left[2a,3a\\right]\">\\left[2a,3a\\right]</span> 上的最小值为 <span class=\"gk-math\" data-tex=\"t\">t</span>，当 <span class=\"gk-math\" data-tex=\"a\">a</span> 变化时，下列一定不成立的是（ ）.","optionsHtml":["<span class=\"gk-math\" data-tex=\"s&gt;0,t&gt;0\">s&gt;0,t&gt;0</span>","<span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>，<span class=\"gk-math\" data-tex=\"t&lt;0\">t&lt;0</span>","<span class=\"gk-math\" data-tex=\"s&lt;0\">s&lt;0</span>，<span class=\"gk-math\" data-tex=\"t&lt;0\">t&lt;0</span>","<span class=\"gk-math\" data-tex=\"s&lt;0\">s&lt;0</span>，<span class=\"gk-math\" data-tex=\"t&gt;0\">t&gt;0</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，<span class=\"gk-math\" data-tex=\"s\">s</span>为 <span class=\"gk-math\" data-tex=\"\\sin x\">\\sin x</span>在 <span class=\"gk-math\" data-tex=\"\\left[a,2a\\right]\">\\left[a,2a\\right]</span>上的最小值，<span class=\"gk-math\" data-tex=\"t\">t</span>为在 <span class=\"gk-math\" data-tex=\"\\left[2a,3a\\right]\">\\left[2a,3a\\right]</span>上的最小值. 若 <span class=\"gk-math\" data-tex=\"t&gt;0\">t&gt;0</span>，则 <span class=\"gk-math\" data-tex=\"\\sin x\">\\sin x</span>在闭区间 <span class=\"gk-math\" data-tex=\"\\left[2a,3a\\right]\">\\left[2a,3a\\right]</span>上恒正，故该连通区间必含于某一个 <span class=\"gk-math\" data-tex=\"\\left(2k\\pi,\\left(2k+1\\right)\\pi\\right)\">\\left(2k\\pi,\\left(2k+1\\right)\\pi\\right)</span>（<span class=\"gk-math\" data-tex=\"k\\ge 0\">k\\ge 0</span>为整数）内，即 <span class=\"gk-math\" data-tex=\"2k\\pi&lt;2a\">2k\\pi&lt;2a</span>且 <span class=\"gk-math\" data-tex=\"3a&lt;\\left(2k+1\\right)\\pi\">3a&lt;\\left(2k+1\\right)\\pi</span>. 由此 <span class=\"gk-math\" data-tex=\"a&gt;k\\pi\">a&gt;k\\pi</span>且 <span class=\"gk-math\" data-tex=\"a&lt;\\frac{\\left(2k+1\\right)\\pi}{3}\">a&lt;\\frac{\\left(2k+1\\right)\\pi}{3}</span>，必有 <span class=\"gk-math\" data-tex=\"k\\pi&lt;\\frac{\\left(2k+1\\right)\\pi}{3}\">k\\pi&lt;\\frac{\\left(2k+1\\right)\\pi}{3}</span>，即 <span class=\"gk-math\" data-tex=\"k&lt;1\">k&lt;1</span>，故 <span class=\"gk-math\" data-tex=\"k=0\">k=0</span>，<span class=\"gk-math\" data-tex=\"3a&lt;\\pi\">3a&lt;\\pi</span>，<span class=\"gk-math\" data-tex=\"a&lt;\\frac{\\pi}{3}\">a&lt;\\frac{\\pi}{3}</span>. 此时 <span class=\"gk-math\" data-tex=\"\\left[a,2a\\right]\\subset\\left(0,\\pi\\right)\">\\left[a,2a\\right]\\subset\\left(0,\\pi\\right)</span>，<span class=\"gk-math\" data-tex=\"\\sin x&gt;0\">\\sin x&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>. 于是 <span class=\"gk-math\" data-tex=\"t&gt;0\">t&gt;0</span>必推出 <span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>，<span class=\"gk-math\" data-tex=\"s&lt;0\">s&lt;0</span>且 <span class=\"gk-math\" data-tex=\"t&gt;0\">t&gt;0</span>不可能. 另方面，取 <span class=\"gk-math\" data-tex=\"a=\\frac{\\pi}{6}\">a=\\frac{\\pi}{6}</span>时两区间的最小值均为正，故 A可成立；取 <span class=\"gk-math\" data-tex=\"a=\\frac{2\\pi}{5}\">a=\\frac{2\\pi}{5}</span>时 <span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>而 <span class=\"gk-math\" data-tex=\"t&lt;0\">t&lt;0</span>，故 B可成立；取 <span class=\"gk-math\" data-tex=\"a=2\\pi\">a=2\\pi</span>时两区间的最小值均为 <span class=\"gk-math\" data-tex=\"-1\">-1</span>，故 C可成立. 因此一定不成立的是 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q16","paperId":"2023-shanghai","number":16,"type":"single","score":5,"lessonIds":["e1-3.1","e1-3.2","3.1"],"difficulty":"挑战","hint":"把点M到曲线的距离能取到哪些值列出来，再检查每个距离的倒数是否也能取到。","legacy":false,"legacyReason":"","searchText":"对于曲线 C ，若存在点 M ，使得对任意的点 P\\in C ，都存在 Q\\in C ，且 \\left|PM\\right|\\cdot\\left|QM\\right|=1 ，则称曲线 C 为“自相关曲线”. 有以下结论： 任何椭圆都是“自相关曲线”； 存在双曲线是“自相关曲线”. 关于上述两个结论，说法正确的是（ ）. 1 成立， 2 成立 1 成立， 2 不成立 1 不成立， 2 成立 1 不成立， 2 不成立","questionHtml":"对于曲线 <span class=\"gk-math\" data-tex=\"C\">C</span>，若存在点 <span class=\"gk-math\" data-tex=\"M\">M</span>，使得对任意的点 <span class=\"gk-math\" data-tex=\"P\\in C\">P\\in C</span>，都存在 <span class=\"gk-math\" data-tex=\"Q\\in C\">Q\\in C</span>，且 <span class=\"gk-math\" data-tex=\"\\left|PM\\right|\\cdot\\left|QM\\right|=1\">\\left|PM\\right|\\cdot\\left|QM\\right|=1</span>，则称曲线 <span class=\"gk-math\" data-tex=\"C\">C</span> 为“自相关曲线”. 有以下结论： <ol class=\"gk-subparts\"><li>任何椭圆都是“自相关曲线”；</li><li>存在双曲线是“自相关曲线”. 关于上述两个结论，说法正确的是（ ）.</li></ol>","optionsHtml":["<span class=\"gk-circled\">1</span> 成立，<span class=\"gk-circled\">2</span> 成立","<span class=\"gk-circled\">1</span> 成立，<span class=\"gk-circled\">2</span> 不成立","<span class=\"gk-circled\">1</span> 不成立，<span class=\"gk-circled\">2</span> 成立","<span class=\"gk-circled\">1</span> 不成立，<span class=\"gk-circled\">2</span> 不成立"],"answerHtml":"B","answerKey":"B","solutionHtml":"记 <span class=\"gk-math\" data-tex=\"d_{M}\\left(P\\right)=\\left|PM\\right|\">d_{M}\\left(P\\right)=\\left|PM\\right|</span>. 若 <span class=\"gk-math\" data-tex=\"M\\in C\">M\\in C</span>，取 <span class=\"gk-math\" data-tex=\"P=M\">P=M</span>则 <span class=\"gk-math\" data-tex=\"\\left|PM\\right|=0\">\\left|PM\\right|=0</span>，任何 <span class=\"gk-math\" data-tex=\"Q\">Q</span>都使乘积为 <span class=\"gk-math\" data-tex=\"0\">0</span>，故 <span class=\"gk-math\" data-tex=\"M\">M</span>必在 <span class=\"gk-math\" data-tex=\"C\">C</span>外. 对紧连通的 <span class=\"gk-math\" data-tex=\"C\">C</span>（椭圆），<span class=\"gk-math\" data-tex=\"d_{M}\">d_{M}</span>的像 <span class=\"gk-math\" data-tex=\"D\">D</span>为连通紧集，即闭区间 <span class=\"gk-math\" data-tex=\"D=\\left[m,M_{d}\\right]\">D=\\left[m,M_{d}\\right]</span>，其中 <span class=\"gk-math\" data-tex=\"m=\\min_{C}d_{M}&gt;0\">m=\\min_{C}d_{M}&gt;0</span>，<span class=\"gk-math\" data-tex=\"M_{d}=\\max_{C}d_{M}\">M_{d}=\\max_{C}d_{M}</span>. 条件化为对一切 <span class=\"gk-math\" data-tex=\"d\\in D\">d\\in D</span>有 <span class=\"gk-math\" data-tex=\"\\frac1d\\in D\">\\frac1d\\in D</span>，当且仅当 <span class=\"gk-math\" data-tex=\"mM_{d}=1\">mM_{d}=1</span>；此时倒数映射恰为该区间到自身的双射. 对任一椭圆 <span class=\"gk-math\" data-tex=\"C\">C</span>，取 <span class=\"gk-math\" data-tex=\"P_{0}\\in C\">P_{0}\\in C</span>及固定方向，令 <span class=\"gk-math\" data-tex=\"M\\left(t\\right)=P_{0}+t\\bs v\">M\\left(t\\right)=P_{0}+t\\bs v</span>（<span class=\"gk-math\" data-tex=\"t\\ge 0\">t\\ge 0</span>），则 <span class=\"gk-math\" data-tex=\"m\\left(t\\right)\">m\\left(t\\right)</span>，<span class=\"gk-math\" data-tex=\"M_{d}\\left(t\\right)\">M_{d}\\left(t\\right)</span>关于 <span class=\"gk-math\" data-tex=\"t\">t</span>均连续，<span class=\"gk-math\" data-tex=\"g\\left(t\\right)=m\\left(t\\right)M_{d}\\left(t\\right)\">g\\left(t\\right)=m\\left(t\\right)M_{d}\\left(t\\right)</span>连续. <span class=\"gk-math\" data-tex=\"t=0\">t=0</span>时 <span class=\"gk-math\" data-tex=\"M\\in C\">M\\in C</span>故 <span class=\"gk-math\" data-tex=\"g=0\">g=0</span>；<span class=\"gk-math\" data-tex=\"C\">C</span>有界而 <span class=\"gk-math\" data-tex=\"\\left|M\\left(t\\right)\\right|\\to+\\infty\">\\left|M\\left(t\\right)\\right|\\to+\\infty</span>，故 <span class=\"gk-math\" data-tex=\"m\\left(t\\right)\\to+\\infty\">m\\left(t\\right)\\to+\\infty</span>，<span class=\"gk-math\" data-tex=\"g\\left(t\\right)\\to+\\infty\">g\\left(t\\right)\\to+\\infty</span>. 由介值定理有 <span class=\"gk-math\" data-tex=\"t^{\\ast}\">t^{\\ast}</span>使 <span class=\"gk-math\" data-tex=\"g=1\">g=1</span>，对应 <span class=\"gk-math\" data-tex=\"M^{\\ast}\">M^{\\ast}</span>满足 <span class=\"gk-math\" data-tex=\"mM_{d}=1\">mM_{d}=1</span>，即为所求. 故任何椭圆都是自相关曲线，<span class=\"gk-circled\">1</span>成立. 设 <span class=\"gk-math\" data-tex=\"C\">C</span>为任一双曲线，则 <span class=\"gk-math\" data-tex=\"C\">C</span>为平面闭无界集. 若 <span class=\"gk-math\" data-tex=\"M\\in C\">M\\in C</span>已不可能如上. 若 <span class=\"gk-math\" data-tex=\"M\\notin C\">M\\notin C</span>，距离函数在闭集 <span class=\"gk-math\" data-tex=\"C\">C</span>上达到最小值 <span class=\"gk-math\" data-tex=\"m=\\min_{C}\\left|PM\\right|&gt;0\">m=\\min_{C}\\left|PM\\right|&gt;0</span>；又 <span class=\"gk-math\" data-tex=\"C\">C</span>无界故距离无上界，取 <span class=\"gk-math\" data-tex=\"P\\in C\">P\\in C</span>使 <span class=\"gk-math\" data-tex=\"\\left|PM\\right|&gt;\\frac1m\">\\left|PM\\right|&gt;\\frac1m</span>，则对一切 <span class=\"gk-math\" data-tex=\"Q\\in C\">Q\\in C</span>有 <span class=\"gk-math\" data-tex=\"\\left|PM\\right|\\cdot\\left|QM\\right|\\ge\\left|PM\\right|m&gt;1\">\\left|PM\\right|\\cdot\\left|QM\\right|\\ge\\left|PM\\right|m&gt;1</span>，无 <span class=\"gk-math\" data-tex=\"Q\">Q</span>使乘积为 <span class=\"gk-math\" data-tex=\"1\">1</span>. 故不存在双曲线是自相关曲线，<span class=\"gk-circled\">2</span>不成立. 于是<span class=\"gk-circled\">1</span>成立<span class=\"gk-circled\">2</span>不成立，选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q17","paperId":"2023-shanghai","number":19,"type":"written","score":14,"lessonIds":["e3-7.1","e3-7.2","e3-7.3"],"difficulty":"进阶","hint":"先把表格四格人数加总；抽两个模型时按“两个都同色、两个都不同、只一项同色”分组计数。","legacy":false,"legacyReason":"","searchText":"2023 年 6 月 7 日，21 世纪汽车博览会在上海举行. 已知某汽车模型公司共有 25 个汽车模型，其外观和内饰的颜色分布如下表所示： 红色外观 蓝色外观 米色内饰 12 8 棕色内饰 2 3 小明从这些汽车模型中随机取出一个，记事件 A 为“小明取到红色外观的汽车模型”，事件 B 为“小明取到棕色内饰的汽车模型”，求 P(B) 和 P(B\\mid A) ，并据此判断事件 A 和事件 B 是否独立； 该公司举行抽奖活动，规定在一次抽奖中，每人可以一次性从这些汽车模型中随机取出两个汽车模型，并给出以下假设： 取出的两个汽车模型会出现三种结果，即外观和内饰均为同色，外观和内饰均不为同色，以及仅外观或仅内饰为同色； 按出现结果的可能性大小，概率越小奖项越高； 抽奖活动的奖金金额为：一等奖 600 元，二等奖 300 元，三等奖 150 元. 请分析各奖项对应的结果，设 X 为奖金额，写出 X 的分布并求其数学期望. ","questionHtml":"2023 年 6 月 7 日，21 世纪汽车博览会在上海举行. 已知某汽车模型公司共有 <span class=\"gk-math\" data-tex=\"25\">25</span> 个汽车模型，其外观和内饰的颜色分布如下表所示：<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td></td><td>红色外观</td><td>蓝色外观</td></tr><tr><td>米色内饰</td><td><span class=\"gk-math\" data-tex=\"12\">12</span></td><td><span class=\"gk-math\" data-tex=\"8\">8</span></td></tr><tr><td>棕色内饰</td><td><span class=\"gk-math\" data-tex=\"2\">2</span></td><td><span class=\"gk-math\" data-tex=\"3\">3</span></td></tr></table></div></div><br><br><ol class=\"gk-subparts\"><li>小明从这些汽车模型中随机取出一个，记事件 A 为“小明取到红色外观的汽车模型”，事件 B 为“小明取到棕色内饰的汽车模型”，求 <span class=\"gk-math\" data-tex=\"P(B)\">P(B)</span> 和 <span class=\"gk-math\" data-tex=\"P(B\\mid A)\">P(B\\mid A)</span>，并据此判断事件 A 和事件 B 是否独立；</li><li>该公司举行抽奖活动，规定在一次抽奖中，每人可以一次性从这些汽车模型中随机取出两个汽车模型，并给出以下假设： <ol class=\"gk-subparts\"><li>取出的两个汽车模型会出现三种结果，即外观和内饰均为同色，外观和内饰均不为同色，以及仅外观或仅内饰为同色；</li><li>按出现结果的可能性大小，概率越小奖项越高；</li><li>抽奖活动的奖金金额为：一等奖 <span class=\"gk-math\" data-tex=\"600\">600</span> 元，二等奖 <span class=\"gk-math\" data-tex=\"300\">300</span> 元，三等奖 <span class=\"gk-math\" data-tex=\"150\">150</span> 元.</li></ol> 请分析各奖项对应的结果，设 <span class=\"gk-math\" data-tex=\"X\">X</span> 为奖金额，写出 <span class=\"gk-math\" data-tex=\"X\">X</span> 的分布并求其数学期望.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>红色外观共有 <span class=\"gk-math\" data-tex=\"12+2=14\">12+2=14</span> 个，棕色内饰共有 <span class=\"gk-math\" data-tex=\"2+3=5\">2+3=5</span> 个，所以 <span class=\"gk-math\" data-tex=\"P(B)=\\frac{5}{25}=\\frac15\">P(B)=\\frac{5}{25}=\\frac15</span>，<span class=\"gk-math\" data-tex=\"P(B\\mid A)=\\frac{2}{14}=\\frac17\">P(B\\mid A)=\\frac{2}{14}=\\frac17</span>. 因为 <span class=\"gk-math\" data-tex=\"P(B\\mid A)\\ne P(B)\">P(B\\mid A)\\ne P(B)</span>，所以事件 <span class=\"gk-math\" data-tex=\"A\">A</span> 和事件 <span class=\"gk-math\" data-tex=\"B\">B</span> 不独立.</li><li>从 <span class=\"gk-math\" data-tex=\"25\">25</span> 个模型中一次取出 <span class=\"gk-math\" data-tex=\"2\">2</span> 个，不计顺序，总取法数为 <span class=\"gk-math\" data-tex=\"\\mathrm C_{25}^{2}=300\">\\mathrm C_{25}^{2}=300</span>. “外观和内饰均为同色”即两模型出自同一格，取法数为 <span class=\"gk-math\" data-tex=\"\\mathrm C_{12}^{2}+\\mathrm C_{8}^{2}+\\mathrm C_{2}^{2}+\\mathrm C_{3}^{2}=66+28+1+3=98\">\\mathrm C_{12}^{2}+\\mathrm C_{8}^{2}+\\mathrm C_{2}^{2}+\\mathrm C_{3}^{2}=66+28+1+3=98</span>，故其概率为 <span class=\"gk-math\" data-tex=\"\\frac{98}{300}=\\frac{49}{150}\">\\frac{98}{300}=\\frac{49}{150}</span>.<br><br>“外观和内饰均不为同色”即外观不同且内饰不同，只能是红米与蓝棕、蓝米与红棕的组合，取法数为 <span class=\"gk-math\" data-tex=\"12\\times 3+8\\times 2=36+16=52\">12\\times 3+8\\times 2=36+16=52</span>，故其概率为 <span class=\"gk-math\" data-tex=\"\\frac{52}{300}=\\frac{13}{75}\">\\frac{52}{300}=\\frac{13}{75}</span>.<br><br>“仅外观或仅内饰为同色”为余下情形，取法数为 <span class=\"gk-math\" data-tex=\"12\\times 2+8\\times 3+12\\times 8+2\\times 3=24+24+96+6=150\">12\\times 2+8\\times 3+12\\times 8+2\\times 3=24+24+96+6=150</span>，与 <span class=\"gk-math\" data-tex=\"300-98-52=150\">300-98-52=150</span>一致，故其概率为 <span class=\"gk-math\" data-tex=\"\\frac{150}{300}=\\frac12\">\\frac{150}{300}=\\frac12</span>.<br><br>由“概率越小奖项越高”可知：<span class=\"gk-math\" data-tex=\"P(X=600)=\\frac{13}{75}\">P(X=600)=\\frac{13}{75}</span>，<span class=\"gk-math\" data-tex=\"P(X=300)=\\frac{49}{150}\">P(X=300)=\\frac{49}{150}</span>，<span class=\"gk-math\" data-tex=\"P(X=150)=\\frac12\">P(X=150)=\\frac12</span>. 因此 <span class=\"gk-math\" data-tex=\"E(X)=600\\times \\frac{13}{75}+300\\times \\frac{49}{150}+150\\times \\frac12=104+98+75=277\">E(X)=600\\times \\frac{13}{75}+300\\times \\frac{49}{150}+150\\times \\frac12=104+98+75=277</span>. 故 <span class=\"gk-math\" data-tex=\"X\">X</span> 的分布列为  <div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td><span class=\"gk-math\" data-tex=\"X\">X</span></td><td><span class=\"gk-math\" data-tex=\"600\">600</span></td><td><span class=\"gk-math\" data-tex=\"300\">300</span></td><td><span class=\"gk-math\" data-tex=\"150\">150</span></td></tr><tr><td><span class=\"gk-math\" data-tex=\"P\">P</span></td><td><span class=\"gk-math\" data-tex=\"\\frac{13}{75}\">\\frac{13}{75}</span></td><td><span class=\"gk-math\" data-tex=\"\\frac{49}{150}\">\\frac{49}{150}</span></td><td><span class=\"gk-math\" data-tex=\"\\frac12\">\\frac12</span></td></tr></table></div> <br> 且 <span class=\"gk-math\" data-tex=\"E(X)=277\">E(X)=277</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q18","paperId":"2023-shanghai","number":17,"type":"written","score":14,"lessonIds":["8.5","8.3","e1-1.4"],"difficulty":"进阶","hint":"证明线面平行先找平行平面中的直线；用体积除以底面积求棱柱高。","legacy":false,"legacyReason":"","searchText":"在四棱柱 ABCD-A_1B_1C_1D_1 中， AB\\parallel DC ， AB\\perp AD ， AB=2 ， AD=3 ， DC=4 . 求证： A_1B\\parallel 平面 DCC_1D_1 ； 若直四棱柱 ABCD-A_1B_1C_1D_1 的体积为 36 ，求二面角 A_1-BD-A 的大小。 ","questionHtml":"在四棱柱 <span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span> 中，<span class=\"gk-math\" data-tex=\"AB\\parallel DC\">AB\\parallel DC</span>，<span class=\"gk-math\" data-tex=\"AB\\perp AD\">AB\\perp AD</span>，<span class=\"gk-math\" data-tex=\"AB=2\">AB=2</span>，<span class=\"gk-math\" data-tex=\"AD=3\">AD=3</span>，<span class=\"gk-math\" data-tex=\"DC=4\">DC=4</span>.<br><br><ol class=\"gk-subparts\"><li>求证：<span class=\"gk-math\" data-tex=\"A_1B\\parallel\">A_1B\\parallel</span>平面<span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>；</li><li>若直四棱柱<span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span>的体积为<span class=\"gk-math\" data-tex=\"36\">36</span>，求二面角<span class=\"gk-math\" data-tex=\"A_1-BD-A\">A_1-BD-A</span>的大小。</li></ol> <figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,551px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/shanghai/q17_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/shanghai/q17_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"535\" height=\"514\" style=\"aspect-ratio:535/514;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为 <span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span> 为四棱柱，所以 <span class=\"gk-math\" data-tex=\"AA_1\\parallel DD_1\">AA_1\\parallel DD_1</span>，<span class=\"gk-math\" data-tex=\"DD_1\\subset\">DD_1\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>，<span class=\"gk-math\" data-tex=\"AA_1\\not\\subset\">AA_1\\not\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>，故 <span class=\"gk-math\" data-tex=\"AA_1\\parallel\">AA_1\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>；又 <span class=\"gk-math\" data-tex=\"AB\\parallel DC\">AB\\parallel DC</span>，<span class=\"gk-math\" data-tex=\"DC\\subset\">DC\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>，<span class=\"gk-math\" data-tex=\"AB\\not\\subset\">AB\\not\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>，故 <span class=\"gk-math\" data-tex=\"AB\\parallel\">AB\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>；<span class=\"gk-math\" data-tex=\"AB\\cap AA_1=A\">AB\\cap AA_1=A</span>，所以平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\\parallel\">ABB_1A_1\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>；<span class=\"gk-math\" data-tex=\"A_1B\\subset\">A_1B\\subset</span> 平面 <span class=\"gk-math\" data-tex=\"ABB_1A_1\">ABB_1A_1</span>，故 <span class=\"gk-math\" data-tex=\"A_1B\\parallel\">A_1B\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"DCC_1D_1\">DCC_1D_1</span>.</li><li>直四棱柱的侧棱垂直于底面. 底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 为直角梯形，面积 <span class=\"gk-math\" data-tex=\"S_{ABCD}=\\frac{AB+DC}{2}\\cdot AD=\\frac{2+4}{2}\\times 3=9\">S_{ABCD}=\\frac{AB+DC}{2}\\cdot AD=\\frac{2+4}{2}\\times 3=9</span>，由体积为 <span class=\"gk-math\" data-tex=\"36\">36</span> 得高 <span class=\"gk-math\" data-tex=\"AA_1=\\frac{36}{9}=4\">AA_1=\\frac{36}{9}=4</span>. 设 <span class=\"gk-math\" data-tex=\"H\">H</span> 为点 <span class=\"gk-math\" data-tex=\"A\">A</span> 在直线 <span class=\"gk-math\" data-tex=\"BD\">BD</span> 上的投影，则 <span class=\"gk-math\" data-tex=\"AH\\perp BD\">AH\\perp BD</span>；因为 <span class=\"gk-math\" data-tex=\"AA_1\\perp\">AA_1\\perp</span> 底面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，所以 <span class=\"gk-math\" data-tex=\"AA_1\\perp BD\">AA_1\\perp BD</span>，故 <span class=\"gk-math\" data-tex=\"BD\\perp\">BD\\perp</span> 平面 <span class=\"gk-math\" data-tex=\"A_1AH\">A_1AH</span>，于是 <span class=\"gk-math\" data-tex=\"A_1H\\perp BD\">A_1H\\perp BD</span>，<span class=\"gk-math\" data-tex=\"\\angle A_1HA\">\\angle A_1HA</span> 即二面角 <span class=\"gk-math\" data-tex=\"A_1-BD-A\">A_1-BD-A</span> 的平面角. 在直角三角形 <span class=\"gk-math\" data-tex=\"ABD\">ABD</span> 中，<span class=\"gk-math\" data-tex=\"BD=\\sqrt{AB^2+AD^2}=\\sqrt{13}\">BD=\\sqrt{AB^2+AD^2}=\\sqrt{13}</span>，<span class=\"gk-math\" data-tex=\"AH=\\frac{AB\\cdot AD}{BD}=\\frac{6}{\\sqrt{13}}\">AH=\\frac{AB\\cdot AD}{BD}=\\frac{6}{\\sqrt{13}}</span>，所以 <span class=\"gk-math\" data-tex=\"\\tan\\angle A_1HA=\\frac{AA_1}{AH}=\\frac{4}{\\frac{6}{\\sqrt{13}}}=\\frac{2\\sqrt{13}}{3}\">\\tan\\angle A_1HA=\\frac{AA_1}{AH}=\\frac{4}{\\frac{6}{\\sqrt{13}}}=\\frac{2\\sqrt{13}}{3}</span>. 故二面角 <span class=\"gk-math\" data-tex=\"A_1-BD-A\">A_1-BD-A</span> 的大小为 <span class=\"gk-math\" data-tex=\"\\arctan\\frac{2\\sqrt{13}}{3}\">\\arctan\\frac{2\\sqrt{13}}{3}</span>.</li></ol>","sourceNote":"已对照独立PDF整理卷核对题干；解析中的计算与推导已复核。","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q19","paperId":"2023-shanghai","number":18,"type":"written","score":14,"lessonIds":["3.2","2.3"],"difficulty":"进阶","hint":"第一问算f(x)+f(−x)；第二问先把f(1)=3代入，再检查分子零点是否被分母排除。","legacy":false,"legacyReason":"","searchText":"设函数 f(x)=\\frac{x^2+(3a+1)x+c}{x+a} ， a ， c\\in\\R 当 a=0 时，是否存在实数 c ，使得 y=f(x) 为奇函数，请说明理由； 若函数 y=f(x) 的图像过点 (1,3) ，且其与 x 轴的负半轴有两个不同的交点，求 c 的值及 a 的取值范围. ","questionHtml":"设函数 <span class=\"gk-math\" data-tex=\"f(x)=\\frac{x^2+(3a+1)x+c}{x+a}\">f(x)=\\frac{x^2+(3a+1)x+c}{x+a}</span>，<span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"c\\in\\R\">c\\in\\R</span> <ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span> 时，是否存在实数 <span class=\"gk-math\" data-tex=\"c\">c</span>，使得 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 为奇函数，请说明理由；</li><li>若函数 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的图像过点 <span class=\"gk-math\" data-tex=\"(1,3)\">(1,3)</span>，且其与 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴的负半轴有两个不同的交点，求 <span class=\"gk-math\" data-tex=\"c\">c</span> 的值及 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span> 时，<span class=\"gk-math\" data-tex=\"f(x)=\\frac{x^2+x+c}{x}=x+1+\\frac{c}{x}\">f(x)=\\frac{x^2+x+c}{x}=x+1+\\frac{c}{x}</span>，定义域为 <span class=\"gk-math\" data-tex=\"x\\ne 0\">x\\ne 0</span>，关于原点对称. 对任意 <span class=\"gk-math\" data-tex=\"x\\ne 0\">x\\ne 0</span>，有 <span class=\"gk-math\" data-tex=\"f(-x)=-x+1-\\frac{c}{x}\">f(-x)=-x+1-\\frac{c}{x}</span>，于是 <span class=\"gk-math\" data-tex=\"f(x)+f(-x)=2\\ne 0\">f(x)+f(-x)=2\\ne 0</span>，即 <span class=\"gk-math\" data-tex=\"f(-x)\\ne -f(x)\">f(-x)\\ne -f(x)</span>，所以不存在实数 <span class=\"gk-math\" data-tex=\"c\">c</span> 使 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 为奇函数.</li><li>由图像过点 <span class=\"gk-math\" data-tex=\"(1,3)\">(1,3)</span>，得 <span class=\"gk-math\" data-tex=\"f(1)=3\\iff \\frac{1+(3a+1)+c}{1+a}=3\">f(1)=3\\iff \\frac{1+(3a+1)+c}{1+a}=3</span>，化简得 <span class=\"gk-math\" data-tex=\"c=1\">c=1</span>. 此时 <span class=\"gk-math\" data-tex=\"f(x)=\\frac{x^2+(3a+1)x+1}{x+a}\">f(x)=\\frac{x^2+(3a+1)x+1}{x+a}</span>，其与 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴的交点由分子 <span class=\"gk-math\" data-tex=\"x^2+(3a+1)x+1=0\">x^2+(3a+1)x+1=0</span> 给出，且根须异于 <span class=\"gk-math\" data-tex=\"-a\">-a</span>. 两根之积为 <span class=\"gk-math\" data-tex=\"1&gt;0\">1&gt;0</span>，故两根同号；要使其为两个不同的负根，需要两根之和为负且判别式大于 <span class=\"gk-math\" data-tex=\"0\">0</span>：<span class=\"gk-math\" data-tex=\"-(3a+1)&lt;0\">-(3a+1)&lt;0</span>，<span class=\"gk-math\" data-tex=\"(3a+1)^2-4&gt;0\">(3a+1)^2-4&gt;0</span>. 前者给出 <span class=\"gk-math\" data-tex=\"a&gt;-\\frac13\">a&gt;-\\frac13</span>，后者在此条件下化为 <span class=\"gk-math\" data-tex=\"3a+1&gt;2\">3a+1&gt;2</span>，即 <span class=\"gk-math\" data-tex=\"a&gt;\\frac13\">a&gt;\\frac13</span>. 此外，当 <span class=\"gk-math\" data-tex=\"a=\\frac12\">a=\\frac12</span> 时，<span class=\"gk-math\" data-tex=\"x^2+\\left(3a+1\\right)x+1=x^2+\\frac52x+1=\\left(x+\\frac12\\right)\\left(x+2\\right)\">x^2+\\left(3a+1\\right)x+1=x^2+\\frac52x+1=\\left(x+\\frac12\\right)\\left(x+2\\right)</span>，与分母 <span class=\"gk-math\" data-tex=\"x+a=x+\\frac12\">x+a=x+\\frac12</span> 约去后，只剩一个负半轴交点，因此还需排除 <span class=\"gk-math\" data-tex=\"a=\\frac12\">a=\\frac12</span>. 故 <span class=\"gk-math\" data-tex=\"c=1\">c=1</span>，<span class=\"gk-math\" data-tex=\"a\\in\\left(\\frac13,\\frac12\\right)\\cup\\left(\\frac12,+\\infty\\right)\">a\\in\\left(\\frac13,\\frac12\\right)\\cup\\left(\\frac12,+\\infty\\right)</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q20","paperId":"2023-shanghai","number":20,"type":"written","score":18,"lessonIds":["e1-3.3","e1-2.3","2.3"],"difficulty":"挑战","hint":"在抛物线上用纵坐标表示横坐标：A=(a²/4,a)，P=(u²/4,u)。","legacy":false,"legacyReason":"","searchText":"已知抛物线 \\Gamma:y^2=4x ，第一象限内点 A 在 \\Gamma 上， A 的纵坐标是 a . 若 A 到准线的距离为 3 ，求 a ； 若 a=4 ， B 在 x 轴上，且线段 AB 的中点在 \\Gamma 上，求点 B 的坐标及坐标原点 O 到直线 AB 的距离； 直线 l:x=-3 ，令 P 是第一象限 \\Gamma 上异于 A 的一点，直线 AP 交 l 于 Q ， H 是 P 在 l 上的投影，若点 A 满足“对于任意 P 都有 \\left|HQ\\right|>4 ”，求 a 的取值范围. ","questionHtml":"已知抛物线 <span class=\"gk-math\" data-tex=\"\\Gamma:y^2=4x\">\\Gamma:y^2=4x</span>，第一象限内点 <span class=\"gk-math\" data-tex=\"A\">A</span> 在 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 上，<span class=\"gk-math\" data-tex=\"A\">A</span> 的纵坐标是 <span class=\"gk-math\" data-tex=\"a\">a</span>. <ol class=\"gk-subparts\"><li>若 <span class=\"gk-math\" data-tex=\"A\">A</span> 到准线的距离为 <span class=\"gk-math\" data-tex=\"3\">3</span>，求 <span class=\"gk-math\" data-tex=\"a\">a</span>；</li><li>若 <span class=\"gk-math\" data-tex=\"a=4\">a=4</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 在 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴上，且线段 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的中点在 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 上，求点 <span class=\"gk-math\" data-tex=\"B\">B</span> 的坐标及坐标原点 <span class=\"gk-math\" data-tex=\"O\">O</span> 到直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的距离；</li><li>直线 <span class=\"gk-math\" data-tex=\"l:x=-3\">l:x=-3</span>，令 <span class=\"gk-math\" data-tex=\"P\">P</span> 是第一象限 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 上异于 A 的一点，直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span> 交 <span class=\"gk-math\" data-tex=\"l\">l</span> 于 <span class=\"gk-math\" data-tex=\"Q\">Q</span>，<span class=\"gk-math\" data-tex=\"H\">H</span> 是 <span class=\"gk-math\" data-tex=\"P\">P</span> 在 <span class=\"gk-math\" data-tex=\"l\">l</span> 上的投影，若点 A 满足“对于任意 <span class=\"gk-math\" data-tex=\"P\">P</span> 都有 <span class=\"gk-math\" data-tex=\"\\left|HQ\\right|&gt;4\">\\left|HQ\\right|&gt;4</span>”，求 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>设点 <span class=\"gk-math\" data-tex=\"A\\left(\\frac{a^2}{4},a\\right)\">A\\left(\\frac{a^2}{4},a\\right)</span>. 抛物线 <span class=\"gk-math\" data-tex=\"y^2=4x\">y^2=4x</span> 的准线为 <span class=\"gk-math\" data-tex=\"x=-1\">x=-1</span>，点 <span class=\"gk-math\" data-tex=\"A\">A</span> 到准线的距离为 <span class=\"gk-math\" data-tex=\"\\frac{a^2}{4}+1\">\\frac{a^2}{4}+1</span>. 由题意 <span class=\"gk-math\" data-tex=\"\\frac{a^2}{4}+1=3\">\\frac{a^2}{4}+1=3</span>，得 <span class=\"gk-math\" data-tex=\"a^2=8\">a^2=8</span>；<span class=\"gk-math\" data-tex=\"A\">A</span> 在第一象限，故 <span class=\"gk-math\" data-tex=\"a=2\\sqrt2\">a=2\\sqrt2</span>.</li><li>当 <span class=\"gk-math\" data-tex=\"a=4\">a=4</span> 时，<span class=\"gk-math\" data-tex=\"A(4,4)\">A(4,4)</span>. 设 <span class=\"gk-math\" data-tex=\"B(x,0)\">B(x,0)</span>，则 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的中点为 <span class=\"gk-math\" data-tex=\"\\left(\\frac{x+4}{2},2\\right)\">\\left(\\frac{x+4}{2},2\\right)</span>. 该点在 <span class=\"gk-math\" data-tex=\"\\Gamma\">\\Gamma</span> 上，所以 <span class=\"gk-math\" data-tex=\"2^2=4\\cdot \\frac{x+4}{2}\">2^2=4\\cdot \\frac{x+4}{2}</span>，解得 <span class=\"gk-math\" data-tex=\"x=-2\">x=-2</span>，故 <span class=\"gk-math\" data-tex=\"B(-2,0)\">B(-2,0)</span>. 直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的方程为 <span class=\"gk-math\" data-tex=\"2x-3y+4=0\">2x-3y+4=0</span>，于是原点 <span class=\"gk-math\" data-tex=\"O\">O</span> 到直线 <span class=\"gk-math\" data-tex=\"AB\">AB</span> 的距离为 <span class=\"gk-math\" data-tex=\"\\frac{4}{\\sqrt{2^2+(-3)^2}}=\\frac{4}{\\sqrt{13}}\">\\frac{4}{\\sqrt{2^2+(-3)^2}}=\\frac{4}{\\sqrt{13}}</span>.</li><li>设 <span class=\"gk-math\" data-tex=\"P\\left(\\frac{u^2}{4},u\\right)\">P\\left(\\frac{u^2}{4},u\\right)</span>，其中 <span class=\"gk-math\" data-tex=\"u&gt;0\">u&gt;0</span> 且 <span class=\"gk-math\" data-tex=\"u\\ne a\">u\\ne a</span>. 又 <span class=\"gk-math\" data-tex=\"A\\left(\\frac{a^2}{4},a\\right)\">A\\left(\\frac{a^2}{4},a\\right)</span>，则直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span> 的斜率为 <span class=\"gk-math\" data-tex=\"\\frac{u-a}{\\frac{u^2-a^2}{4}}=\\frac{4}{u+a}\">\\frac{u-a}{\\frac{u^2-a^2}{4}}=\\frac{4}{u+a}</span>. 由此得直线 <span class=\"gk-math\" data-tex=\"AP\">AP</span> 与 <span class=\"gk-math\" data-tex=\"x=-3\">x=-3</span> 交于 <span class=\"gk-math\" data-tex=\"Q\\left(-3,\\frac{au-12}{u+a}\\right)\">Q\\left(-3,\\frac{au-12}{u+a}\\right)</span>. 而 <span class=\"gk-math\" data-tex=\"H(-3,u)\">H(-3,u)</span>，故 <span class=\"gk-math\" data-tex=\"\\left|HQ\\right|=\\left|u-\\frac{au-12}{u+a}\\right|=\\frac{u^2+12}{u+a}\">\\left|HQ\\right|=\\left|u-\\frac{au-12}{u+a}\\right|=\\frac{u^2+12}{u+a}</span>，其中最后一个等号是因为 <span class=\"gk-math\" data-tex=\"\\frac{u^2+12}{u+a}&gt;0\">\\frac{u^2+12}{u+a}&gt;0</span>. 题设要求 <span class=\"gk-math\" data-tex=\"\\frac{u^2+12}{u+a}&gt;4\">\\frac{u^2+12}{u+a}&gt;4</span> 对任意 <span class=\"gk-math\" data-tex=\"u&gt;0\">u&gt;0</span>，<span class=\"gk-math\" data-tex=\"u\\ne a\">u\\ne a</span> 成立，即 <span class=\"gk-math\" data-tex=\"u^2-4u+12-4a&gt;0\">u^2-4u+12-4a&gt;0</span>. 左边视为关于 <span class=\"gk-math\" data-tex=\"u\">u</span> 的二次函数，其最小值在 <span class=\"gk-math\" data-tex=\"u=2\">u=2</span> 处取得，最小值为 <span class=\"gk-math\" data-tex=\"8-4a\">8-4a</span>. 因此若 <span class=\"gk-math\" data-tex=\"a&lt;2\">a&lt;2</span>，则不等式恒成立；若 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span>，则左边化为 <span class=\"gk-math\" data-tex=\"(u-2)^2\">(u-2)^2</span>，其等号只在 <span class=\"gk-math\" data-tex=\"u=2\">u=2</span> 处取得，而这时 <span class=\"gk-math\" data-tex=\"P=A\">P=A</span> 被排除，所以仍成立；若 <span class=\"gk-math\" data-tex=\"a&gt;2\">a&gt;2</span>，取 <span class=\"gk-math\" data-tex=\"u=2\">u=2</span>（此时 <span class=\"gk-math\" data-tex=\"u\\ne a\">u\\ne a</span>，允许）即不成立. 又 <span class=\"gk-math\" data-tex=\"A\">A</span> 在第一象限，故 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>. 所以 <span class=\"gk-math\" data-tex=\"a\\in\\left(0,2\\right]\">a\\in\\left(0,2\\right]</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-shanghai-q21","paperId":"2023-shanghai","number":21,"type":"written","score":18,"lessonIds":["e2-5.1","e2-5.3","e2-4.1"],"difficulty":"挑战","hint":"切线碰到y轴时x=0，先求切线截距，得到后一项和前一项的关系。","legacy":false,"legacyReason":"","searchText":"已知 f(x)=\\ln x . 曲线 y=f(x) 在点 \\left(a_1,f(a_1)\\right) 处的切线交 y 轴于点 (0,a_2) ，且 a_2>0 ；曲线 y=f(x) 在点 \\left(a_2,f(a_2)\\right) 处的切线交 y 轴于点 (0,a_3) ；以此类推，直至 a_m\\le 0 时停止，得到数列 \\{a_n\\} . 证明：当正整数 n\\ge 2 时， a_n=\\ln a_{n-1}-1 ； 当正整数 n\\ge 2 时，试比较 a_n 与 a_{n-1}-2 的大小； 若正整数 k\\ge 3 ，是否存在 k 使得 a_1 ， a_2 ， \\cdots ， a_k 依次成等差数列？若存在，求出 k 的所有取值；若不存在，试说明理由. ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"f(x)=\\ln x\">f(x)=\\ln x</span>. 曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在点 <span class=\"gk-math\" data-tex=\"\\left(a_1,f(a_1)\\right)\">\\left(a_1,f(a_1)\\right)</span> 处的切线交 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴于点 <span class=\"gk-math\" data-tex=\"(0,a_2)\">(0,a_2)</span>，且 <span class=\"gk-math\" data-tex=\"a_2&gt;0\">a_2&gt;0</span>；曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在点 <span class=\"gk-math\" data-tex=\"\\left(a_2,f(a_2)\\right)\">\\left(a_2,f(a_2)\\right)</span> 处的切线交 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴于点 <span class=\"gk-math\" data-tex=\"(0,a_3)\">(0,a_3)</span>；以此类推，直至 <span class=\"gk-math\" data-tex=\"a_m\\le 0\">a_m\\le 0</span> 时停止，得到数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span>. <ol class=\"gk-subparts\"><li>证明：当正整数 <span class=\"gk-math\" data-tex=\"n\\ge 2\">n\\ge 2</span> 时，<span class=\"gk-math\" data-tex=\"a_n=\\ln a_{n-1}-1\">a_n=\\ln a_{n-1}-1</span>；</li><li>当正整数 <span class=\"gk-math\" data-tex=\"n\\ge 2\">n\\ge 2</span> 时，试比较 <span class=\"gk-math\" data-tex=\"a_n\">a_n</span> 与 <span class=\"gk-math\" data-tex=\"a_{n-1}-2\">a_{n-1}-2</span> 的大小；</li><li>若正整数 <span class=\"gk-math\" data-tex=\"k\\ge 3\">k\\ge 3</span>，是否存在 <span class=\"gk-math\" data-tex=\"k\">k</span> 使得 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，<span class=\"gk-math\" data-tex=\"\\cdots\">\\cdots</span>，<span class=\"gk-math\" data-tex=\"a_k\">a_k</span> 依次成等差数列？若存在，求出 <span class=\"gk-math\" data-tex=\"k\">k</span> 的所有取值；若不存在，试说明理由.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>曲线 <span class=\"gk-math\" data-tex=\"y=\\ln x\">y=\\ln x</span> 在点 <span class=\"gk-math\" data-tex=\"\\left(a_{n-1},\\ln a_{n-1}\\right)\">\\left(a_{n-1},\\ln a_{n-1}\\right)</span> 处的切线方程为 <span class=\"gk-math\" data-tex=\"y-\\ln a_{n-1}=\\frac1{a_{n-1}}\\left(x-a_{n-1}\\right)\">y-\\ln a_{n-1}=\\frac1{a_{n-1}}\\left(x-a_{n-1}\\right)</span>. 令 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span>，得该切线与 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴的交点纵坐标为 <span class=\"gk-math\" data-tex=\"\\ln a_{n-1}-1\">\\ln a_{n-1}-1</span>，所以 <span class=\"gk-math\" data-tex=\"a_n=\\ln a_{n-1}-1\">a_n=\\ln a_{n-1}-1</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"\\ln x\\le x-1\">\\ln x\\le x-1</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>，当且仅当 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 时取等号）得 <span class=\"gk-math\" data-tex=\"a_n=\\ln a_{n-1}-1\\le a_{n-1}-1-1=a_{n-1}-2\">a_n=\\ln a_{n-1}-1\\le a_{n-1}-1-1=a_{n-1}-2</span>，当且仅当 <span class=\"gk-math\" data-tex=\"a_{n-1}=1\">a_{n-1}=1</span> 时取等号.</li><li>记 <span class=\"gk-math\" data-tex=\"h(x)=\\e^{x+1}+\\ln x-1-2x\">h(x)=\\e^{x+1}+\\ln x-1-2x</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>）. 若 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，<span class=\"gk-math\" data-tex=\"a_3\">a_3</span> 成等差数列，则 <span class=\"gk-math\" data-tex=\"a_1+a_3=2a_2\">a_1+a_3=2a_2</span>. 由 （1） 知 <span class=\"gk-math\" data-tex=\"a_1=\\e^{a_2+1}\">a_1=\\e^{a_2+1}</span>，且 <span class=\"gk-math\" data-tex=\"a_3=\\ln a_2-1\">a_3=\\ln a_2-1</span>，故 <span class=\"gk-math\" data-tex=\"h(a_2)=0\">h(a_2)=0</span>. 又 <span class=\"gk-math\" data-tex=\"h^{\\prime}(x)=\\e^{x+1}+\\frac1x-2&gt;0\">h^{\\prime}(x)=\\e^{x+1}+\\frac1x-2&gt;0</span>（<span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>，因为 <span class=\"gk-math\" data-tex=\"\\e^{x+1}&gt;\\e&gt;2\">\\e^{x+1}&gt;\\e&gt;2</span>），所以 <span class=\"gk-math\" data-tex=\"h(x)\">h(x)</span> 在 <span class=\"gk-math\" data-tex=\"(0,+\\infty)\">(0,+\\infty)</span> 上严格递增. 并且 <span class=\"gk-math\" data-tex=\"\\displaystyle\\lim_{x\\to 0^+}h(x)=-\\infty\">\\displaystyle\\lim_{x\\to 0^+}h(x)=-\\infty</span>，<span class=\"gk-math\" data-tex=\"h(1)=\\e^2-3&gt;0\">h(1)=\\e^2-3&gt;0</span>，故方程 <span class=\"gk-math\" data-tex=\"h(x)=0\">h(x)=0</span> 在 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span> 内有唯一解，从而存在唯一的 <span class=\"gk-math\" data-tex=\"a_2\\in(0,1)\">a_2\\in(0,1)</span> 使得 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，<span class=\"gk-math\" data-tex=\"a_3\">a_3</span> 成等差数列. 此时 <span class=\"gk-math\" data-tex=\"a_3=\\ln a_2-1&lt;0\">a_3=\\ln a_2-1&lt;0</span>，所以序列在 <span class=\"gk-math\" data-tex=\"a_3\">a_3</span> 处停止，即 <span class=\"gk-math\" data-tex=\"m=3\">m=3</span>；任何 <span class=\"gk-math\" data-tex=\"k\\ge 4\">k\\ge 4</span> 的等差数列都须以同样的 <span class=\"gk-math\" data-tex=\"a_1\">a_1</span>，<span class=\"gk-math\" data-tex=\"a_2\">a_2</span>，<span class=\"gk-math\" data-tex=\"a_3\">a_3</span> 开头，与序列已终止矛盾. 故存在 <span class=\"gk-math\" data-tex=\"k\">k</span>，且 <span class=\"gk-math\" data-tex=\"k\">k</span> 的所有取值为 <span class=\"gk-math\" data-tex=\"k=3\">k=3</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
